parameters.text:
=You are a B2B sales SDR assistant. Score the following inbound lead as HOT, WARM, or COLD based on buying intent, budget, authority, timeline, and company fit (BANT).

Respond with ONLY a valid JSON object, no markdown, no extra text, in exactly this shape:
{"score":"HOT|WARM|COLD","reasoning":"one concise sentence","key_signals":["signal1","signal2"]}

LEAD:
Name: {{ $json.name }}
Email: {{ $json.email }}
Company: {{ $json.company }}
Message: {{ $json.message }}

parameters.jsCode:
// Parse Gemini output leniently + build a personalized outreach draft
const raw = ($json.text || $json.response || $json.output || JSON.stringify($json)) + '';

// pull the score keyword
let score = 'COLD';
const m = raw.toUpperCase().match(/\b(HOT|WARM|COLD)\b/);
if (m) score = m[1];

// try to extract JSON block for reasoning/signals
let reasoning = '';
let signals = [];
try {
  const jmatch = raw.match(/\{[\s\S]*\}/);
  if (jmatch) {
    const parsed = JSON.parse(jmatch[0]);
    if (parsed.score) score = String(parsed.score).toUpperCase().match(/HOT|WARM|COLD/)?.[0] || score;
    reasoning = parsed.reasoning || '';
    if (Array.isArray(parsed.key_signals)) signals = parsed.key_signals;
  }
} catch (e) { /* lenient */ }
if (!reasoning) reasoning = raw.replace(/\s+/g,' ').trim().slice(0, 240);

// lead fields (came from prior node via chain — re-read from the incoming item)
const lead = $('AI Lead Scorer').first().json;
// fall back to source lead nodes
let name='there', email='', company='', message='';
try { const src = $items(0).length ? null : null; } catch(e){}
try {
  const s = $('Sample Lead').first().json; name=s.name; email=s.email; company=s.company; message=s.message;
} catch(e) {}
try {
  const w = $('Normalize Webhook Lead').first().json; if (w && w.email) { name=w.name; email=w.email; company=w.company; message=w.message; }
} catch(e) {}

const first = (name||'there').split(' ')[0];
const tone = score === 'HOT' ? 'Given your approved budget and tight timeline, I can jump on a call this week.'
  : score === 'WARM' ? 'Happy to share a short demo tailored to your workflow whenever you are ready.'
  : 'I have put together a few resources that might help as you explore automation.';

const draft = `Subject: ${company.split('(')[0].trim()} × automation — quick next step\n\nHi ${first},\n\nThanks for reaching out about automating your support/dispatch pipeline. ${reasoning} ${tone}\n\nWould a 20-minute walkthrough work? I'll show a live n8n flow mapped to your exact use case.\n\nBest,\nSales Team`;

return [{ json: { name, email, company, message, score, reasoning, key_signals: signals, outreach_draft: draft, scored_at: new Date().toISOString() } }];

